    init{
        val queue=java.util.ArrayDeque<TreeNode>();
        queue.addLast(root);
        while(queue.isNotEmpty()){
            val node=queue.removeFirst();
            if(node.left==null||node.right==null)candidates.addLast(node);
            node.left?.let{
                queue.addLast(it)
            };
            node.right?.let{
                queue.addLast(it)
            }
        }
    };
    fun insert(value:Int):Int{
